   818	        /// In until mode, called after the byte just before `end` has been
   819	        /// fully processed. Completes the stop if that byte reached a
   820	        /// requested boundary (including ground, which is also checked
   821	        /// here) and returns true when the caller must return.
   822	        inline fn untilReached(self: *Self, u: *Until, end: [*]const u8) bool {
   823	            const at_ground = u.boundaries.contains(.ground) and self.ground();
   824	            if (u.stop == null and !at_ground) return false;
   825	            const stop = u.stopPtr();
   826	            stop.consumed = @intFromPtr(end) - @intFromPtr(u.base);
