   738	            if (self.continuation != null) self.trackContinuation(input);
   739	        }
   740	
   741	        /// Process input until the first byte that reaches one of
   742	        /// `boundaries`, and stop right after that byte.
   743	        ///
   744	        /// Returns the stop, or null if the whole input was consumed
   745	        /// without reaching a boundary. Only the consumed bytes are
   746	        /// processed, so handler actions never run for bytes after the
   747	        /// stop. Feed the rest of the input in a later call.
   748	        ///
   749	        /// The bytes consumed across a series of calls are exactly the
   750	        /// bytes the stream parsed, in order, and a second stream fed those
   751	        /// same bytes is in the same parser state at every stop. This is
   752	        /// what a proxy that sits between a program and a terminal needs.
   753	        /// It can find exactly where a control string starts and ends, or
   754	        /// wait for a safe point before inserting its own output, using
   755	        /// the same parse that drives its terminal.
   756	        ///
   757	        /// `.ground` is a state, not an event. If the stream is already at
   758	        /// ground, this consumes nothing and returns a stop with
   759	        /// `consumed == 0`. A loop that keeps asking for `.ground` with the
   760	        /// same input never makes progress. After a ground stop, feed the
   761	        /// next bytes without `.ground` in the set, or with `nextSlice`.
   762	        ///
   763	        /// This loop finds the content of every APC string in `input`.
   764	        /// DCS and OSC strings work the same way with their own
   765	        /// boundaries:
   766	        ///
   767	        /// ```zig
   768	        /// const set: Boundary.Set = .initMany(&.{ .apc_start, .apc_end });
   769	        /// var rest = input;
   770	        /// var content_start: ?usize = null;
   771	        /// while (stream.nextSliceUntil(rest, set)) |stop| {
   772	        ///     const offset = input.len - rest.len;
   773	        ///     if (stop.start != null) content_start = offset + stop.consumed;
   774	        ///     if (stop.end != null) {
   775	        ///         // The ending byte is consumed but is not content.
   776	        ///         const content_end = offset + stop.consumed - 1;
   777	        ///         handleApc(input[content_start.?..content_end]);
   778	        ///     }
   779	        ///     rest = rest[stop.consumed..];
   780	        /// }
   781	        /// ```
   782	        ///
   783	        /// The loop needs no special case for a string that ends with the
   784	        /// two-byte terminator `ESC \`. The stop lands on the ESC, and the
   785	        /// backslash is just the next byte of `rest`.
   786	        ///
   787	        /// Asking for `.ground` costs 1% to 5% over `nextSlice`, because the
   788	        /// stream has to leave its fast path at every return to ground.
   789	        /// Asking only for string boundaries costs nothing on the bulk
   790	        /// paths that handle text and string payloads, and a little for
   791	        /// each byte of an escape sequence. Every check is compiled out
   792	        /// of `nextSlice`, so its code is unchanged whether or not this
   793	        /// function is used.
   794	        pub inline fn nextSliceUntil(
   795	            self: *Self,
   796	            input: []const u8,
   797	            boundaries: Boundary.Set,
   798	        ) ?Boundary.Stop {
   799	            if (boundaries.contains(.ground) and self.ground()) return .{
   800	                .consumed = 0,
   801	                .reached = .initOne(.ground),
   802	            };
   803	
   804	            var u: Until = .{
   805	                .boundaries = boundaries,
   806	                .base = input.ptr,
   807	            };
   808	            self.nextSliceUntracked(input, true, &u);
   809	
   810	            const consumed = if (u.stop) |stop| stop.consumed else input.len;
   811	            if (self.continuation != null and consumed > 0) {
   812	                self.trackContinuation(input[0..consumed]);
   813	            }
   814	
   815	            return u.stop;
   816	        }
   817	
   818	        /// In until mode, called after the byte just before `end` has been
   819	        /// fully processed. Completes the stop if that byte reached a
   820	        /// requested boundary (including ground, which is also checked
   821	        /// here) and returns true when the caller must return.
   822	        inline fn untilReached(self: *Self, u: *Until, end: [*]const u8) bool {
   823	            const at_ground = u.boundaries.contains(.ground) and self.ground();
   824	            if (u.stop == null and !at_ground) return false;
   825	            const stop = u.stopPtr();
   826	            stop.consumed = @intFromPtr(end) - @intFromPtr(u.base);
   827	            if (at_ground) stop.reached.insert(.ground);
   828	            return true;
   829	        }
   830	
   831	        inline fn nextSliceUntracked(
   832	            self: *Self,
   833	            input: []const u8,
   834	            comptime until: bool,
   835	            u: Until.Arg(until),
   836	        ) void {
   837	            // Byte-at-a-time parsing in debug mode only. Even without
   838	            // SIMD support (build_options.simd == false, e.g. wasm), the
   839	            // batched path below is much faster than per-byte dispatch
   840	            // because it decodes UTF-8 in bulk (via scalar fallbacks) and
   841	            // hands printable runs to the handler as print_slice actions.
   842	            if (comptime debug) {
   843	                for (input, 0..) |c, i| {
   844	                    self.nextUntracked(c, until, u);
   845	                    if (comptime until) {
   846	                        if (self.untilReached(u, input.ptr + i + 1)) return;
   847	                    }
   848	                }
   849	                return;
   850	            }
   851	
   852	            // This is the maximum number of codepoints we can decode
   853	            // at one time for this function call. This is somewhat arbitrary
   854	            // so if someone can demonstrate a better number then we can switch.
   855	            var cp_buf: [4096]u32 = undefined;
   856	
   857	            // Split the input into chunks that fit into cp_buf.
   858	            var i: usize = 0;
   859	            while (true) {
   860	                const len = @min(cp_buf.len, input.len - i);
   861	                self.nextSliceCapped(input[i .. i + len], &cp_buf, until, u);
   862	                if (comptime until) if (u.stop != null) return;
   863	                i += len;
   864	                if (i >= input.len) break;
   865	            }
   866	        }
   867	
   868	        inline fn nextSliceCapped(
   869	            self: *Self,
   870	            input: []const u8,
   871	            cp_buf: []u32,
   872	            comptime until: bool,
   873	            u: Until.Arg(until),
   874	        ) void {
   875	            assert(input.len <= cp_buf.len);
   876	
   877	            var offset: usize = 0;
   878	
   879	            // If the scalar UTF-8 decoder was in the middle of processing
   880	            // a code sequence, we continue until it's not.
   285	    data: termio.Termio.ThreadData = undefined,
   286	};
